//! Embed everything the compiler needs, so the binary depends on nothing.
//!
//! Three wasm artifacts, two slot maps, and the guest source flint ships -- the
//! standard library, `flint.deps` and `flint.cli` -- already READ by the kin
//! reader (`DECISIONS.md#stdlib-preread`): its forms, not its text.
//! They are GENERATED by `bin/build-dist`, not tracked, so this fails with a
//! sentence rather than with a missing-file error from `include_bytes!`.
use std::{env, fs, path::Path};

fn main() {
    let root = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().to_path_buf();
    let dist = root.join("dist");
    // The compiler as BYTECODE rather than as a module: this binary runs it
    // natively and has no wasm engine to run a module in. The format is an
    // implementation detail, embedded and never written out.
    for f in ["flintc.bytecode", "flint-runtime.wasm", "flint-runtime-aot.wasm",
              "slots.json", "slots-aot.json"] {
        if !dist.join(f).exists() {
            panic!("dist/{f} is missing. It is generated: run `bin/build-dist` first.");
        }
    }
    println!("cargo:rerun-if-changed={}", dist.display());
    // THE GUEST SOURCE THIS BINARY SHIPS, as four source roots, each owned by
    // CONTAINMENT (`DECISIONS.md#four-units`): the standard library's two
    // layers, both owned by `lib/deps.edn` one directory up; `flint.deps` in
    // `lib/deps/`; and `flint.cli` in `cli/lib/`. Embedded with the root that
    // holds each file, so `main.rs` gives every file its own root's workspace
    // rather than guessing one from a namespace prefix -- which is what it did
    // until the units had roots of their own (`"flint/deps"` ahead of
    // `"clojure/"` and `"flint/"`).
    const ROOTS: [&str; 4] = ["lib/stdcore", "lib/stdextra", "lib/deps", "cli/lib"];
    println!("cargo:rerun-if-changed={}", root.join("lib").display());
    println!("cargo:rerun-if-changed={}", root.join("cli/lib").display());

    let mut entries: Vec<(String, String, usize)> = Vec::new();
    fn walk(dir: &Path, prefix: &str, r: usize, out: &mut Vec<(String, String, usize)>) {
        let mut names: Vec<_> = fs::read_dir(dir).unwrap().filter_map(|e| e.ok()).collect();
        names.sort_by_key(|e| e.path());
        for e in names {
            let p = e.path();
            let name = p.file_name().unwrap().to_string_lossy().to_string();
            let rel = if prefix.is_empty() { name.clone() } else { format!("{prefix}/{name}") };
            if p.is_dir() {
                walk(&p, &rel, r, out);
            // `flint.compiler.resolve/source-extensions` is the list that decides which
            // file WINS for a namespace; this one only decides what is worth
            // embedding, so a superset costs a read and a SUBSET loses a file
            // silently.
            } else if rel.ends_with(".fln") || rel.ends_with(".cljc") || rel.ends_with(".clj") {
                out.push((rel, fs::read_to_string(&p).unwrap(), r));
            }
        }
    }
    // The `deps.edn` that owns a root: its own, or the one a directory up --
    // the rule `bin/flint`'s `project-of` and `bin/build-stdlib-forms` follow.
    let owner = |dir: &Path| -> String {
        for p in [dir.join("deps.edn"), dir.parent().unwrap().join("deps.edn")] {
            if let Ok(t) = fs::read_to_string(&p) {
                return t;
            }
        }
        String::new()
    };
    let mut src = String::from("pub static STDLIB_ROOTS: &[(&str, &str)] = &[\n");
    for (r, rel) in ROOTS.iter().enumerate() {
        let dir = root.join(rel);
        walk(&dir, "", r, &mut entries);
        src.push_str(&format!("  ({rel:?}, {:?}),\n", owner(&dir)));
    }
    src.push_str("];\n");
    entries.sort_by(|a, b| a.0.cmp(&b.0));
    for w in entries.windows(2) {
        if w[0].0 == w[1].0 {
            panic!("{} is in both {} and {}", w[0].0, ROOTS[w[0].2], ROOTS[w[1].2]);
        }
    }

    // The stdlib's OWN `deps.edn`, by name, for what still asks about the
    // standard library's workspace in particular (`resolve.rs`'s tests).
    let lib_deps = fs::read_to_string(root.join("lib/deps.edn")).unwrap_or_default();
    src.push_str(&format!("pub static STDLIB_DEPS: &str = {:?};\n", lib_deps));

    // ALREADY READ, and not as text at all (`DECISIONS.md#stdlib-preread`): by
    // the kin reader every door reads with (`flint_rt::hostread`), DEFERRED, so
    // one read serves every feature set -- the reader keeps `#?` as data and
    // each compile resolves it. THE DIALECT IS PASSED, from the extension, and
    // embedded beside the bytes, so the compile is told it rather than
    // re-deriving it from a path (`DECISIONS.md#four-units`). This used to run
    // the embedded compiler's `preread` mode, which read with the compiler's
    // own reader, since deleted (`DECISIONS.md#one-reader-and-no-other`).
    let out = Path::new(&env::var("OUT_DIR").unwrap()).to_path_buf();
    let mut rt = flint_rt::rt::Rt::new();
    let mut blob = Vec::new();
    src.push_str("pub static STDLIB_INDEX: &[(&str, usize, usize, usize, &str)] = &[\n");
    let text: usize = entries.iter().map(|e| e.1.len()).sum();
    for (path, body, r) in &entries {
        let portable = !path.ends_with(".fln");
        let how = flint_rt::hostread::ReadAs { features: None, tags: &[], portable };
        let bytes = flint_rt::hostread::read_text(&mut rt, path, body, &how)
            .unwrap_or_else(|e| panic!("{}/{path} does not read: {}", ROOTS[*r], e.message));
        let a = blob.len();
        blob.extend_from_slice(&bytes);
        let dialect = if portable { "portable" } else { "flint" };
        src.push_str(&format!("  ({path:?}, {a}, {}, {r}, {dialect:?}),\n", blob.len()));
    }
    src.push_str("];\n");
    fs::write(out.join("stdlib.forms"), &blob).unwrap();
    src.push_str("pub static STDLIB_FORMS: &[u8] = include_bytes!(concat!(env!(\"OUT_DIR\"), \"/stdlib.forms\"));\n");
    fs::write(out.join("stdlib.rs"), src).unwrap();
    println!("cargo:warning=pre-read {} guest source files: {} bytes of forms from {} bytes of text",
             entries.len(), blob.len(), text);
}
